"use strict";
/* 识字 · Zeichentrainer — standalone PWA
   Persistence via IndexedDB (survives restarts). Camera inbox. Offline. */

/* ---------- Deck (in code, survives everything) ---------- */
/* No built-in deck any more (v33): every card comes from H's photos or the Add form. */

const NEW_PER_SESSION = 8;
const CJK = /[\u4e00-\u9fff]/;
const pySpaced=t=>{ const out=[]; for(const x of pinyinPro.pinyin(t,{type:"array",toneType:"symbol"})){ const prev=out[out.length-1]; if(prev!==undefined&&/^[\d.]+[a-zA-Z%]*$/.test(prev)&&/^[\da-zA-Z%.]$/.test(x)&&!(/[a-zA-Z%]$/.test(prev)&&/[\d.]/.test(x))) out[out.length-1]=prev+x; else out.push(x); } return out.join(" "); }; /* syllables with tone marks, space-separated; a number stays one token (30, not 3 0), with the unit letters the library hands out one by one (380ml, not 380 m l — v323) */
const APP_V=591; /* must equal the PWA vN label in index.html — the boot check repairs a shell whose files are of different versions */
let PICKING=0; const PICK_MAX=10*60000, picking=()=>PICKING>0&&Date.now()-PICKING<PICK_MAX; /* a photo is being taken or picked (v316): from the tap on Take photo or From album until the input's change or cancel, at most ten minutes — no update reload meanwhile, see reloadSoon */
const glyphs = s => [...String(s)].filter(ch => CJK.test(ch)).length;
const headFont = s => { const n = glyphs(s); return n<=1?150:n===2?104:n===3?74:n<=8?58:n<=12?44:34; };

/* ---------- SRS (SM-2 light) ---------- */
const DAY = 86400000;
const LEECH_FAILS = 4; /* "again" this many times in a row flags the card for review */
const startOfDay = t => { const d = new Date(t); d.setHours(0,0,0,0); return d.getTime(); };
const today = () => startOfDay(Date.now());
/* the screen offers three grades since v421 — Hard = "again", Medium = "good", Easy — so "hard" is no longer reachable
   from the card; it stays here for the progress rows written by it and for the fails rule below */
function schedule(card, grade){
  let ease = card ? card.ease : 2.5;
  let interval = card ? card.interval : 0;
  const reps = (card ? card.reps : 0) + 1;
  if (grade==="again"){ ease=Math.max(1.3,ease-0.2); interval=0; }
  else if (grade==="hard"){ ease=Math.max(1.3,ease-0.15); interval=interval<1?1:Math.round(interval*1.2); }
  else if (grade==="good"){ interval=interval<1?1:Math.round(interval*ease); }
  else if (grade==="easy"){ ease+=0.15; interval=interval<1?3:Math.round(interval*ease*1.3); }
  const due = grade==="again" ? today() : today()+interval*DAY;
  /* consecutive failures — a leech is usually a bad card, not a bad memory */
  const fails = grade==="again" ? ((card&&card.fails)||0)+1 : grade==="hard" ? ((card&&card.fails)||0) : 0;
  return { interval, ease, due, reps, fails, last:today() };
}

/* ---------- IndexedDB (persistent) ---------- */
const DB_NAME="zeichentrainer", DB_VER=3;
let _db=null;
function openDB(){
  return new Promise((res,rej)=>{
    if(_db) return res(_db);
    const r=indexedDB.open(DB_NAME,DB_VER);
    r.onupgradeneeded=e=>{
      const db=r.result, tx=r.transaction;
      if(!db.objectStoreNames.contains("inbox"))    db.createObjectStore("inbox",{keyPath:"id"});
      if(!db.objectStoreNames.contains("settings")) db.createObjectStore("settings",{keyPath:"k"}); /* v2: opt-ins, keys */
      /* v3 (v118): cards and progress are keyed by an id, not by the text — the same characters may be saved again from
         another photo (H). Existing rows keep their text as the id, so nothing else changes for them. */
      for(const name of ["progress","custom"]){
        if(!db.objectStoreNames.contains(name)){ db.createObjectStore(name,{keyPath:"id"}); continue; }
        if(e.oldVersion>=3) continue;
        const rows=[]; const cur=tx.objectStore(name).openCursor();
        cur.onsuccess=()=>{ const c=cur.result; if(c){ rows.push(c.value); c.continue(); return; }
          db.deleteObjectStore(name); const os=db.createObjectStore(name,{keyPath:"id"});
          for(const row of rows) os.put({...row,id:row.id||row.c}); };
      }
    };
    r.onsuccess=()=>{ _db=r.result; res(_db); };
    r.onerror=()=>rej(r.error);
  });
}
function _os(store,mode){ return openDB().then(db=>db.transaction(store,mode).objectStore(store)); }
function idbPut(store,val){ return _os(store,"readwrite").then(os=>new Promise((res,rej)=>{const r=os.put(val);r.onsuccess=()=>res();r.onerror=()=>rej(r.error);})); }
function idbDel(store,key){ return _os(store,"readwrite").then(os=>new Promise((res,rej)=>{const r=os.delete(key);r.onsuccess=()=>res();r.onerror=()=>rej(r.error);})); }
function idbAll(store){ return _os(store,"readonly").then(os=>new Promise((res,rej)=>{const r=os.getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error);})); }
function idbPutMany(store,rows){ return _os(store,"readwrite").then(os=>new Promise((res,rej)=>{ const tx=os.transaction; rows.forEach(r=>os.put(r)); tx.oncomplete=()=>res(); tx.onerror=()=>rej(tx.error); tx.onabort=()=>rej(tx.error); })); } /* all rows in one transaction: all or nothing (v264, the translation applied together) */
function idbClear(store){ return _os(store,"readwrite").then(os=>new Promise((res,rej)=>{const r=os.clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error);})); }

/* a card into the deck and the store: replace by key or append; storage errors are swallowed like everywhere else */
/* v539: the two writes that lose the learner's own work said nothing when they failed. A phone at its storage quota
   keeps the card in memory, shows it as saved and has lost it by the next start, with an empty error log — the v404
   class (a failure that only ever reached the console) one store along. They reach the error log now, so Diagnostics,
   the daily row and All users carry it. Deliberately NOT setSetting: logErr writes a setting itself, so logging its
   own failure would recurse; the v399 head line reports how full the storage is, which is that one's signal. */
async function putCard(upd,key){
  const k=key||upd.id, i=S.custom.findIndex(x=>x.id===k);
  if(i>=0) S.custom[i]=upd; else S.custom.push(upd);
  try{ await idbPut("custom",upd); }catch(e){ logErr("save","card "+k+": "+e); }
}
/* ---------- State ---------- */
const S = { mode:"study", progress:{}, custom:[], inbox:[],
  queue:[], idx:0, done:0, ahead:false, ready:false, /* v583 (H: "Whole Card per Default immer noch zugeklappt"): the block at the card's foot comes up FOLDED again and each of the fourteen S.ansOpen=false lines is back — v581 had read "Details direkt in Whole Card zeigen" as "the block stands open" and removed them; what he meant was the card's own description, which stands at the foot outside the fold since. */ /* v539: `revealed` is gone — it was set to false in ten places and to true in none since v512 replaced tap-to-reveal with the write pad, so every one of those lines was a no-op standing in for `ansOpen`, which is the answer block's own flag */
  pendingImg:null, pendingFull:null, pendingUse:"crop", persist:null,
  peek:null, /* Learn: the id of a linked card whose photo is shown on the front instead (v155) */
  cueBig:"pic", /* which half of the cue is big — "pic" or "txt", NEVER neither: v580 (H: "nur 2 Stati: Karte komplett offen / Übersetzung komplett offen. Tippen toggelt zwischen beiden") took the halves away, so a tap swaps the two states rather than folding one back. A render must not change it — H writes a whole card off the enlarged half (v568). A fresh start is the photo (v572, H: "Start with the open image by default."), a reload the session's own state (v569). */
  admin:false, /* the owner's rows in More unlocked for this session (v162) */
  ownerOpen:false, /* v547: the owner's own block folded behind one row, so More is the same length unlocked as locked */
  detail:null, detailHide:false, fullPic:false, query:"", filterUnv:false, filterFlag:false, filterAi:false, filterStar:false, filterNew:false, filterTags:[], settings:{}, single:null, saved:null, cardsTab:"cards",
  editing:null, editFrom:null, editSeq:0, draft:null, pendingShot:null,
  autoCard:window.AUTO_CARD!==false, editOpenFrame:false, openShot:null }; /* autoCard (v325): a photo that opens by itself becomes a card without a frame or a preview; the harness sets window.AUTO_CARD=false to keep the crop-mode flow its frame suites drive */

function deck(){ return S.custom; }
/* the order of a Learn session (v153, H: "provide choices for the order in which the flash cards are shown"): due cards
   still come before new ones; inside each group "oldest" is the old order (due by due date, new by creation), "newest"
   is by creation newest first, "random" a fresh shuffle per session — setting learnOrder, chosen in More → Learning */
const LEARN_ORDERS=[["oldest","Oldest first"],["newest","Newest first"],["random","Random"]];
const learnOrder=()=>LEARN_ORDERS.some(([v])=>v===S.settings.learnOrder)?S.settings.learnOrder:"oldest";
function orderCards(list,order,byDue){
  if(order==="random"){ const a=list.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }
  if(order==="newest") return list.slice().sort((a,b)=>(b.at||0)-(a.at||0));
  return byDue?list.slice().sort((a,b)=>S.progress[a.id].due-S.progress[b.id].due):list.slice(); /* the deck is oldest first already */
}
/* the cards the Learn filter lets through — all of them, the tags picked in the filter sheet (several allowed since v366,
   a card in any of them counts, v133/v156), or the starred ones (v425); a card still reading has no text yet (v237).
   One filter rule, read by the session and by the pull-forward alike — two copies would drift (the v401 lesson).
   `star` says whether the star filter really applied, which the session needs (v429): it stands down when nothing in
   reach is starred, and then the session is an ordinary one. */
/* a card Learn can study at all (v500): it has a text, and it is neither a multicard nor one of a multicard's own texts —
   nothing on a multicard is studied, counted or scheduled (H's rule, v487). Every count that says "learned", "due",
   "known" or offers a Learn filter reads this one predicate, so the Progress tiles, the deck bar, the Learn sheet's
   numbers and the session can never disagree about what is in the deck. */
const learnable=d=>!!(d&&d.c&&!isPage(d)&&!hiddenCard(d));
const learnPool=()=>deck().filter(learnable);
function learnDeck(){
  const lt=learnTags(); const d=(lt.length?deck().filter(x=>lt.some(g=>hasTag(x,g))):deck()).filter(learnable); /* a page is studied through its items (v453), and since v478 only through the ones that earned a card of their own */
  const star=!!S.settings.learnStar&&d.some(x=>x.star); /* a filter that would empty the session stands down */
  const nw=!!S.settings.learnNew&&d.some(unchecked); /* v515: Not yet checked, the same shape as the star — a hand-picked list, not a category */
  let cards=star?d.filter(x=>x.star):d; if(nw) cards=cards.filter(unchecked);
  return {cards, star, nw};
}
/* the next cards of the same filter by due date, the ones a pull-forward would reach, skipping what the session already holds (v428) */
function buildQueue(includeAhead){
  const p=S.progress, t=today(); const {cards:d,star,nw}=learnDeck();
  const order=learnOrder();
  /* the order of the session (v512, H: "Karten mit Charaktern, die häufig vorkommen, werden öfters angezeigt. Schreiben dieser
     Character stuft Anzeigehäufigkeit wieder herab."): inside the due group and the new group the cards are sorted by weight,
     highest first — the mean over the card's characters of freq/(1+writes), freq the number of learnable cards carrying the
     character and writes how often it was fully written (setting charWrites). A card of common, never-written characters
     comes first; every full write of a character halves its pull. Oldest and Newest decide among equal weights; Random
     ignores the weight altogether (Q7: a random session is random). */
  const freq={}; for(const x of d) for(const ch of new Set([...String(x.c)].filter(ch=>CJK.test(ch)))) freq[ch]=(freq[ch]||0)+1;
  const cw=charWrites(), weightOf=x=>{ const cs=[...String(x.c)].filter(ch=>CJK.test(ch)); if(!cs.length) return 0; return cs.reduce((a,ch)=>a+(freq[ch]||0)/(1+(cw[ch]||0)),0)/cs.length; };
  /* v524 (H: "Bitte jede Lernsession mit kurzen Karten anfangen und dann im Laufe der Zeit immer längere Ausdrücke
     zulassen", "Go A"): inside the due group and inside the new group the cards come by their character count, short
     first — 供应 before 骑车勿盯还车勿忘 —, the weight above deciding among cards of one length and Oldest/Newest among
     equal weights; the due cards still lead the new ones, so a session ramps up twice, and Random stays random. */
  const lenOf=x=>[...String(x.c)].filter(ch=>CJK.test(ch)).length;
  const byWeight=list=>order==="random"?list:list.map((x,i)=>({x,i,w:weightOf(x),n:lenOf(x)})).sort((a,b)=>a.n-b.n||b.w-a.w||a.i-b.i).map(o=>o.x);
  const newFirst=list=>[...list.filter(unchecked),...list.filter(x=>!unchecked(x))]; /* v515: a card not yet checked comes first in its group, whatever the order — checking is what a new card is for */
  const due = newFirst(byWeight(orderCards(d.filter(x=>p[x.id] && p[x.id].due<=t),order,true))).map(x=>x.id);
  /* A star is a hand-picked short list, not a category, so a starred session holds every starred card (v429, H: "Go" on the
     recommendation): the due ones first, so the plan still leads, then the new ones — without the eight-card cap, which exists
     to stop a learner drowning in new cards and not to withhold the ones they picked themselves — then the rest by due date.
     The pill counts 11 and the session now holds 11. A tag stays as it was: a tag can be the whole deck. */
  const all = newFirst(byWeight(orderCards(d.filter(x=>!p[x.id]),order,false))).map(x=>x.id);
  const fresh = star||nw?all:all.slice(0,NEW_PER_SESSION); /* the Not yet checked session holds every unchecked card, as the starred one holds every star (v515) */
  let q=[...due,...fresh];
  if(star) q=[...q,...d.filter(x=>p[x.id]&&p[x.id].due>t).sort((a,b)=>p[a.id].due-p[b.id].due).map(x=>x.id)];
  if(includeAhead && q.length===0)
    q = d.filter(x=>p[x.id]).sort((a,b)=>p[a.id].due-p[b.id].due).slice(0,8).map(x=>x.id);
  return q;
}
const cardOf = id => deck().find(d=>d.id===id); /* cards are addressed by id everywhere; the text is c */
/* The page card (v453, H, 2026-09-13, on the nine cards his Meituan order screen made: "Ich hatte doch gesagt, bitte bei
   Screenshots nicht für jeden Wortstring eine einzelne Karte anlegen, sondern den Screenshot unter Cards und in learn
   speichern mit den Punkten drauf." — the D7 of SPEC-photo-mode.md, built): a screenshot, or a picture the model calls an
   app screen, makes ONE card for the whole page — kind "page", its title the model's name for the screen ("Meituan — order
   confirmation, 颐堤港店"), the whole photo its picture, the texts on it its items. The items are the split's own cards as
   before (text, pinyin, meaning, frame, crop, progress row, AI check, Translate all — everything that already works),
   each carrying page:<the page's id>, and the page carries items:[their ids]; what changes is what the learner sees: one
   row under Cards with the photo and the title, one detail with the dots and the item list, the Camera tab's marked
   photo with the title over its line, and Learn walking the page's texts one after the other (buildQueue groups them).
   The Deck capsule counts neither the page nor its items (v504; v453–v503 counted the page once). A page is never sent to the AI and never studied itself:
   every batch over the deck skips it (isPage), and an item whose page is gone is an ordinary card again (inPage). */
const isPage=d=>!!(d&&d.kind==="page");
const pageItems=pg=>(pg&&pg.items||[]).map(cardOf).filter(Boolean);
const inPage=d=>!!(d&&d.page&&cardOf(d.page)); /* an item of a page that still exists: the list shows the page, not the item */
/* the star is the learner's own mark on a FLASHCARD (v425). A multicard is a reference and not a flashcard, and its own
   texts are its rows — never in the Cards list, never in Learn, never in the Deck count (v487) —, so a star on either is a
   write nothing ever reads (H, v493: "ich darf in einer multicard kein sternchen setzen koennen. Nur in Cards."). The
   control is gone from both, and this predicate makes a star an older build left on one INERT rather than unreachable: it
   would otherwise count in the filter sheet's Starred row and switch a filter on over a list that can never show it, which
   is the v308 trap. Nothing is deleted — the field stays on the record and in the export. */
const starred=d=>!!(d&&d.star)&&!isPage(d)&&!inPage(d);
const deckCount=()=>deck().filter(d=>!isPage(d)&&!hiddenCard(d)).length; /* flashcards only — neither a multicard nor its texts (v504); until v503 the multicard counted once (v453) */
const tabCount=()=>tabPool().length; /* the Cards count is the open tab's own (v477) */
const pageOfShot=shot=>deck().find(d=>isPage(d)&&d.shot===shot)||null;
/* A MULTICARD IS A REFERENCE AND A FLASHCARD IS A FLASHCARD (v487, H, 2026-09-14, across three messages, the last two
   reversing v478 outright: "Forget the idea of creating flash cards from multi cards. That doesn't work. Just have flash
   cards and have multi cards. Don't mix it up." · "Let's have the vote button red and green) in the multicard when you
   open one of those items in the multicard. But now we have to figure out how to handle the multicards during learning."
   · "Every field in the multicards has a button that says generate flashcard. And that flashcard is generated without
   image. It's just a text. But within that card is a reference to the original multicard And/or its name.")

   NOTHING ON A MULTICARD IS STUDIED. Its texts stay exactly what v453 made them — cards with their own progress row,
   star, flag, tags and AI check — but they are the multicard's own rows and never enter Learn, the Cards list or the
   Deck count (`hiddenCard` is `inPage`, full stop, where v478 made an exception for a promoted one). Tapping one gives
   the two-button vote — red Not yet, green Got it — which writes THAT TEXT's progress row, so the multicard's own marks
   and its "N texts, M learned" line mean something again; and **Generate flashcard**, which makes a SEPARATE card of it.

   The generated card is text only: characters, pinyin, meaning, no `img`, no `imgFull`, no `shot`, no `frame`, no
   `page` — so it has no crop to be wrong, no page front and no "N of M" pill, which is what H was looking at when he
   said the derived card was "total missverständlich". It carries `from` (the multicard's id) and `fromT` (its title as
   it stood). The live title wins and `fromT` is only read when the multicard is gone, so the copy is a fallback and
   never a second truth (the v401 lesson).

   WHAT WENT WITH v478, and it went whole: `derived`, the two unfitted thresholds (a text on two multicards, three
   look-ups of one), the `lookups` counter in settings, `promote`/`promoteCheck`, the source carousel, the "From a
   multicard" pill, the multicard chip on the Cards tile, and `groupPages` (there are no page items in a queue to group).
   Nothing automatic is left: you press the button or nothing happens. */
const hiddenCard=d=>inPage(d); /* an item of a page is listed and studied through its page, never on its own */
/* the multicard a generated flashcard came from, and its name: the page itself while it exists, else the title that was
   copied onto the card when it was made */
function srcPage(d){ if(!d||!d.from) return null; const pg=cardOf(d.from); return (pg&&isPage(pg))?pg:null; }
const srcName=d=>{ const pg=srcPage(d); return pg?(pg.c||""):(d&&d.fromT||""); };
/* the flashcard generated from this multicard text, if there is one — derived from the deck rather than stored on the
   item, so deleting the flashcard makes the button offer to generate again by itself (the v401 lesson) */
const madeFrom=item=>item&&item.page&&item.c?deck().find(x=>x.from===item.page&&(x.of?x.of===item.id:x.c===item.c)):null; /* by the item's id since v503 (`of`), so an edit on either side keeps the tie; a card made before v503 carries no `of` and still matches by its text */
/* Generate flashcard (H: "that flashcard is generated without image. It's just a text"). The item keeps everything it
   has; a new card is written beside it with its own id and its own progress, so the two never fight over one row. */
async function makeFlashcard(id){ const d=cardOf(id); if(!d||!d.page||!d.c) return null;
  const have=madeFrom(d); if(have) return have;
  const pg=cardOf(d.page), rec={ id:cardId(d.c), c:d.c, p:d.p||"", m:d.m||"", t:d.t||"Custom", at:Date.now(),
    from:d.page, of:d.id, fromT:(pg&&pg.c)||"", v:APP_V }; /* `of` (v503): WHICH text of the multicard, so a corrected character on either side does not strip the card of its picture and its reference */
  if(d.trad) rec.trad=d.trad;
  /* the text's own review state travels with the card (v503): a flag with its note, the reader's other readings the AI check
     needs, and a waiting AI suggestion — until v502 the card was born clean of all four, so a text H had flagged as wrong
     made a flashcard that said nothing was wrong */
  if(d.flag){ rec.flag=true; if(d.flagNote) rec.flagNote=d.flagNote; }
  if(d.unchecked) rec.unchecked=true; /* v515: the text's own "not yet checked" travels with the card, as its flag does */
  if(d.alts&&d.alts.length) rec.alts=d.alts.slice();
  if(d.ai) rec.ai={...d.ai};
  if(d.ml) rec.ml=d.ml; if(d.ms) rec.ms={...d.ms};
  if(d.seg) rec.seg=d.seg.slice(); if(d.segs) rec.segs=d.segs.slice(); if(d.gloss) rec.gloss=d.gloss.slice();
  if(d.kind==="sign") rec.kind="sign";
  if(d.tags&&d.tags.length) rec.tags=d.tags.slice();
  if(d.mt) rec.mt={...d.mt};
  await putCard(rec);
  /* a card made on purpose joins TODAY's session, at its end — the session is built at boot and nothing else rebuilds
     it, so without this the reward for pressing the button would be a card that appears after the next reload.
     Appending is what an "again" grade already does (v428), so the place in the queue is not disturbed. */
  if(!S.queue.includes(rec.id)) S.queue.push(rec.id);
  return rec; }
/* the cards v478 had promoted, once (v487): they carry `derived` and still sit inside their page, so without this they
   would simply vanish from the deck the day this ships. Each becomes the flashcard the button would have made, and its
   progress row is copied onto the new id, so nothing of H's study history is lost. */
async function migrateDerived(){
  const old=deck().filter(x=>x.derived&&x.page&&x.c); if(!old.length) return 0;
  let n=0;
  for(const x of old){
    const made=await makeFlashcard(x.id);
    if(made&&S.progress[x.id]&&!S.progress[made.id]){ const pr={...S.progress[x.id],id:made.id}; S.progress[made.id]=pr; await idbPut("progress",pr); }
    const {derived,...rest}=x; await putCard(rest); n++;
  }
  return n;
}
function pageTitle(ai,first){ const g=(ai&&ai.pageInfo)||{}; let s=[g.name,g.what].filter(Boolean).join(" — "); if(g.place) s+=(s?", ":"")+g.place; return s||((kindTag(ai&&ai.kind)||t("kind:App"))+" — "+String(first||"").replace(/\n/g," ")); }
/* Tags (v133, H: "make the cards sortable, for Chinese class, HSK …"): free labels on a card, several allowed; the
   forms offer the labels already in use as chips, and the Cards tab and the Learn tab each filter by any number of them (v366) */
const parseTags=str=>[...new Set(String(str||"").split(/[,，;；]/).map(t=>t.trim()).filter(Boolean))];
const allTags=()=>[...new Set(deck().flatMap(d=>d.tags||[]))].sort((a,b)=>a.localeCompare(b));
/* the kind of a card made from a photo (v364, H: "Could you automatically label the Cards?"): one word from a fixed set,
   asked of the AI inside the answer it already gives — no extra call —, stored as an ordinary tag in the app's language,
   so it shows on the card, filters the Cards list and gives Learn a chip, and can be edited or deleted like H's own
   labels. A picture the model is not sure of gets no tag rather than a wrong one. */
const KINDS=["Menu","Street sign","Shop","Product","Appliance","Transport","Office","Notice","App"];
const kindTag=k=>{ const w=String(k||"").trim().toLowerCase(), hit=KINDS.find(x=>x.toLowerCase()===w); return hit?t("kind:"+hit):""; };
/* "Untagged" (v156, H: "provide a default tag for not-tagged cards"): a group, not a label written on the cards — the
   Cards tab and the Learn tab offer it as a row in the filter sheet (v365) while tags exist and some cards carry none; a card that gets a tag
   leaves the group by itself, exports are untouched */
const UNTAGGED="__untagged__";
const hasTag=(d,t)=>t===UNTAGGED?!(d.tags&&d.tags.length):(d.tags||[]).includes(t);
