const numCards=(id,ids)=>numSet(id,"cards",ids.slice(0,40));
const numFrames=fs=>{ const a=fs.filter(Boolean)[0]; return a?{lw:n1(a.lw),lh:n1(a.lh),f:fs.map(r=>r?[n1(r.x),n1(r.y),n1(r.w),n1(r.h),n1(r.a||0)]:null)}:null; }; /* many frames of one layer: the layer once, the rectangles after it */
/* the picture answer as every later decision reads it (v399, measured on H's washing machine: the whole object is 2 931
   bytes for 19 labels, this is 1 390 — 73 a label —, and it is what templateBoxes, roundGrid, picBox/picScale, mainLines
   and snapBox all consume. The raw reply stays in AILOG, where v395 gave it 6 000 characters; this is the same answer
   after the app has read it, so the two can be compared and a misreading of the model's numbers shows up as the
   difference between them. */
const numPic=p=>p?{pw:p.picW,ph:p.picH,box:numFrac(p.box),alt:numFrac(p.boxAlt),sc:p.boxScale||null,model:p.model||"",
  boxes:Array.isArray(p.boxes)?p.boxes.map(numFrac):null,drop:(p.dropped||[]).map(x=>String(x).slice(0,24)),dropB:(p.droppedBoxes||[]).map(numFrac),
  out:(p.outside||[]).map(x=>String(x).slice(0,24)),
  cut:p.cut||"",bad:!!p.bad,apart:!!p.apart,kind:p.kind||"",keptAll:p.keptAll||"",page:p.pageInfo||null,zh:String(p.zh||"").slice(0,200),
  labels:(p.labels||[]).map(l=>({zh:l.zh,box:numFrac(l.box),sc:l.scale}))}:null;
/* NUMS_KEEP was 3 from v405 to v504 ("three covers a photo taken, looked at and taken again") and is 100 since v505, declared with AI_KEEP above */
const LOG_MAX=40, LOG_PRE_KEEP=4, LOG_OLD_HEAD=5, LOG_OLD_TAIL=10; /* v479: steps kept per reading (the 40 the one global list used to hold), the frame's own lines carried into the reading that follows, and how much of an earlier reading is printed — head and tail, so the proposal and the quick look stand at one end and the outcome at the other */
const NUMS_OLD=6000; /* the older two are trimmed harder than the newest: a 19-label panel measures 6.1 KB whole, so this
   keeps a panel intact and costs at most 12 KB of the diagnostics H pastes into a chat */
const NUMS_MAX=12000; /* one reading's numbers, measured on this build: an ordinary sign 1.9 KB, H's 19-label washing machine
   6.1 KB, and about 180 bytes a label after that — so SPLIT_MAX 30 labels come to roughly 8 KB and fit whole. Past the cap
   the blocks go in the order they are worth least: the quick look's boxes first (the reader path does not use them), then
   each label's rectangle in the copy, and the run search's own result last, since that is the one the panel work needs. */
function numsTrim(o,cap){ const max=cap||NUMS_MAX; if(!o) return o;
  const o2={...o}; delete o2.log; delete o2.passes; delete o2.ringed; /* v479: the steps and the passes live on the record now and are printed as their own lines — inside this JSON they would eat the numbers' own budget; ringed is bookkeeping */
  if(JSON.stringify(o2).length<=max) return o2;
  const c={...o2}; for(const k of ["qk","lrects","best","found"]){ if(c[k]!==undefined){ c[k]="dropped, over "+max+" characters"; if(JSON.stringify(c).length<=max) break; } } return c; }
/* a fingerprint of the system prompt (v399): picSystem() is 7 200 characters and changed at v361, v363, v367, v377, v449 and v455, so an
   answer cannot be attributed to a prompt without one — the version says which code, this says which words it actually sent */
const strHash=s=>{ let h=5381; for(let i=0;i<s.length;i++) h=(h*33^s.charCodeAt(i))>>>0; return h.toString(36); };
/* navigator.storage.estimate() is async and diagText is not, so the numbers are taken at boot and whenever More is drawn.
   They matter more than they look: setSetting swallows every write error and saveReadLog, saveAiLog and logErr each end in
   .catch(()=>{}), so a phone at its quota stops persisting the diagnostics and says nothing about it — the v384 failure
   mode with no signal at all. */
const STORAGE={};
async function storageFacts(){ try{ if(navigator.storage&&navigator.storage.estimate){ const e=await navigator.storage.estimate(); STORAGE.quota=e.quota||0; STORAGE.usage=e.usage||0; }
    if(navigator.storage&&navigator.storage.persisted) STORAGE.persisted=await navigator.storage.persisted(); }catch(e){} }
/* one reading, one row (v505): the record trimmed to NUMS_MAX, its steps and its passes beside it, not inside it (v479's
   rule — numsTrim spends a fixed character budget on the numbers, and steps in that JSON would push the numbers out, the
   v395 fault one store along). Debounced per record, so a reading's steps write its own few kilobytes 0.8 s after the
   last one and never anybody else's. The passes ride along for every reading now; Diagnostics still prints the newest
   reading's only. */
let _rdSeq=0; const readRow=N=>{ if(!N.seq) N.seq=++_rdSeq; return {shot:N.shot,at:N.at||0,seq:N.seq,nums:numsTrim(N,NUMS_MAX),log:(N.log||[]).slice(-LOG_MAX),passes:N.passes||null}; }; /* seq breaks a tie on at — two records of one millisecond would otherwise fall back to the rows' key order, which is alphabetical */
const _readlogT=new Map();
const saveReadLog=N=>{ if(!N||!N.shot) return; clearTimeout(_readlogT.get(N.shot));
  _readlogT.set(N.shot,setTimeout(()=>{ _readlogT.delete(N.shot); if(LAST_READ.ring.includes(N)||NUMSOF[N.shot]===N) putRow("read:"+N.shot,readRow(N)); },800)); }; /* a record the ring has already pushed out, or a reset has taken, writes nothing */
const readRestore=row=>{ if(!row||!row.nums) return null; const N={...row.nums}; N.log=Array.isArray(row.log)?row.log.slice(-LOG_MAX):[]; if(row.passes) N.passes=row.passes; if(!N.at) N.at=row.at||0; N.seq=row.seq||0; N.ringed=true; return N; };
function logErr(kind,msg){ ERRLOG.push({t:Date.now(),kind,msg:String(msg||"").slice(0,400)}); while(ERRLOG.length>ERR_KEEP) ERRLOG.shift(); setSetting("errlog",ERRLOG.slice()).catch(()=>{}); }
window.addEventListener("error",e=>logErr("error",(e.message||"")+(e.filename?` @${String(e.filename).split("/").pop()}:${e.lineno}`:"")));
window.addEventListener("unhandledrejection",e=>{ const r=e.reason; logErr("promise",r&&(r.stack||r.message)||r); });
function diagText(){
  const ago=t=>{ const d=Math.round((Date.now()-t)/1000); return d<60?d+" s ago":d<3600?Math.round(d/60)+" min ago":Math.round(d/3600)+" h ago"; };
  const out=[`Zeichentrainer diagnostics — ${new Date().toLocaleString("en-GB")}`,
    `page ${pageVersion()||"?"} · script ${APP_V} · online ${navigator.onLine} · AI ${aiOn()?aiProvider()+(aiLive()?" live":" off")+(textProvider()!==aiProvider()?` (text ${textProvider()})`:""):"none"} · SW ${swControls()?"yes":"no"+(SW_REG?` (registration ${SW_REG})`:"")}${VENDOR.base?` · reader files from ${VENDOR.base===originVendor()?"github.io":"the mirror"}`:""}`,
    /* what the pipeline actually ran on (v399): poolSize() gives 1 on a phone of 3 GB or less and 3 or 4 otherwise, and the
       number of readers decides which passes exist at all and therefore the competition's agreement bonus — a reading cannot
       be reproduced without it. The storage numbers say whether the diagnostics are still being written down (see STORAGE). */
    `cores ${navigator.hardwareConcurrency||"?"} · memory ${navigator.deviceMemory||"?"} GB · readers ${(_pool?_pool.length:0)}/${poolSize()}${STORAGE.quota?` · storage ${((STORAGE.usage||0)/1048576).toFixed(1)} of ${Math.round(STORAGE.quota/1048576)} MB${STORAGE.persisted?", persistent":""}`:" · storage not measured"}`,
    /* the settings the same photo would be read differently under: the app's language goes into picSystem() through
       meaningLangName(), so a German phone gets another answer for the same picture */
    `settings · lang ${LANG} · picture to the AI ${S.settings.aiPicture===false?"off":"on"} · relay ${S.settings.aiRelay===false?"off":"on"} · auto check ${S.settings.aiAuto===false?"off":"on"} · offline model ${S.settings.nmt?"on":"off"} · mirror ${S.settings.mirror===undefined?"default":(S.settings.mirror||"off")} · brightening ${S.settings.brightPass?"done":"not yet"} · re-cut ${recutLine()}`,
    `marks on the photo · ${markLine()}`,
    `main thread · long tasks ${LONG.n}${LONG.n?` (${Math.round(LONG.total)} ms in all, longest ${Math.round(LONG.max)} ms, last ${ago(LONG.at)})`:""} · parse strokes ${PARSE_MS.strokes==null?"not yet":PARSE_MS.strokes+" ms"}, outlines ${PARSE_MS.outlines==null?"not yet":PARSE_MS.outlines+" ms"} · resizes ${RESIZES.length?RESIZES.map(r=>r.bfcache?"back from the cache "+ago(r.t):`${r.from.join("×")}→${r.to.join("×")} ${ago(r.t)}`).join("; "):"none"}`, /* v532: what a fold did to the page, for H's next dump */
    `learn fit · ${LAST_FIT?Object.entries(LAST_FIT).filter(([k])=>k!=="at").map(([k,v])=>k+" "+v).join(", ")+" ("+ago(LAST_FIT.at)+")":"no study card measured yet"}`, /* v521: the pad's last measurement — where the card ends against the tab bar, and what was counted under the pad */
    navigator.userAgent, `voices (${voiceList().length}): ${voiceList().join("; ")||"none reported"}`, ""];
  /* v479: every block is one photo's own. The steps used to be a single global list that the next reading wiped, so an album
     batch mixed two photos' lines into one block and the two earlier readings had no steps at all — only their numbers. */
  const stepLines=(N,ind,head,tail)=>{ const a=(N&&N.log)||[], o=[], drop=head&&a.length>head+tail?a.length-head-tail:0;
    a.forEach((x,i)=>{ if(drop&&i===head) o.push(`${ind}\u2026 ${drop} step${drop===1?"":"s"} left out`);
      if(!drop||i<head||i>=head+drop) o.push(`${ind}${ago(x.t)}  ${x.text}`); });
    return o; };
  const now=lastRead();
  out.push(`Last reading (${now&&now.log?now.log.length:0} steps)${now&&now.shot?" \u00b7 "+now.shot:""}:`);
  if(now){ out.push(...stepLines(now,"  ",0,0));
    if(now.passes) out.push("  passes: "+JSON.stringify(now.passes));
    out.push("  numbers: "+JSON.stringify(numsTrim(now))); } /* the frame chain's own values, unrounded (v399) — the prose above is for reading, this is what a harness is fed */
  /* the two readings before it (v405): a card that came out wrong is rarely from the last photo taken. Their steps are
     trimmed head and tail, which keeps the frame's proposal and the quick look at one end and the outcome at the other;
     their passes are left out, since three competitions would be some 12 KB of a text H pastes into a chat by hand. */
  const older=LAST_READ.ring.filter(N=>N&&N!==now);
  if(older.length){ out.push("", `Earlier readings (${older.length}, newest last):`);
    older.forEach(N=>{ out.push(`  ${ago(N.at)}  ${N.shot||"?"}${Array.isArray(N.cards)?` \u00b7 ${N.cards.length} card${N.cards.length===1?"":"s"}`:""}`);
      if(N.log&&N.log.length){ out.push(`    steps (${N.log.length}):`); out.push(...stepLines(N,"      ",LOG_OLD_HEAD,LOG_OLD_TAIL)); }
      out.push("    numbers: "+JSON.stringify(numsTrim(N,NUMS_OLD))); }); }
  /* DRAWLOG holds two shapes since v512: the drawing sheet's {strokes,alts,…} (v140) and the write pad's {pad,k,ok,dist} — one
     line per traced stroke (logPadStroke). Until v556 this read x.strokes.length off every entry, so the first stroke traced in
     Learn broke Diagnostics for the rest of the session (six "Cannot read properties of undefined" in H's own error log, one per
     tap on Show) and a reload, which empties the memory-only list, made it work again. */
  const drawn=DRAWLOG.filter(x=>Array.isArray(x.strokes)), traced=DRAWLOG.filter(x=>!Array.isArray(x.strokes));
  out.push("", `Drawings (${drawn.length}, newest last):`);
  drawn.forEach(x=>{ out.push(`  ${ago(x.t)}  ${x.strokes.length} stroke${x.strokes.length===1?"":"s"} → ${(x.alts||[]).join(" ")||"nothing"}${x.strokes_best?` · strokes ${x.strokes_best.join(" ")} · print ${(x.ocr||[]).join(" ")||"nothing"}`:""}`); out.push("    strokes: "+JSON.stringify(x.strokes)); });
  out.push(`Traced strokes on the pad (${traced.length}, newest last):`);
  traced.forEach(x=>out.push(x.hand
    ? `  ${ago(x.t)}  ${x.pad||"?"} written freehand, ${x.hand.n} strokes — ${x.ok?"accepted":"not this character"}${x.hand.rank==null?"":", rank "+(x.hand.rank+1)}${x.dist==null?"":", cost "+x.dist}` /* v570: every whole-character judgement, so the field can say how often a real hand is accepted */
    : `  ${ago(x.t)}  ${x.pad||"?"} stroke ${(x.k|0)+1} ${x.ok?"snapped":"missed"}${x.dist==null?"":" at "+x.dist}`)); /* the distance is against TRACE_OK 0.18 of the pad (§ 14) */
  out.push("", `AI exchanges (${AILOG.length}, newest last):`);
  AILOG.forEach(x=>{ out.push(`  ${ago(x.t)}  ${x.model||""} → ${x.status||""}${x.ms?` in ${(x.ms/1000).toFixed(1)} s`:""}`); out.push("    request: "+x.req); out.push("    reply: "+(x.res||x.err||"")); });
  out.push("", `Errors (${ERRLOG.length}):`);
  ERRLOG.forEach(x=>out.push(`  ${ago(x.t)}  [${x.kind}] ${x.msg}`));
  return out.join("\n")+"\n";
}
/* ---------- the owner's report of all phones (v197, H: "show an all-users report, password protected") ----------
   the edge function usage-report (supabase/functions/usage-report) checks the app password against its secret and
   answers with the latest row of every phone plus today's relay calls; the app keeps the password only in memory after
   the unlock (S.adminPw) and sends it with the request — the table itself stays unreadable for the publishable key */
const reportUrl=()=>SHARE_URL+"/functions/v1/usage-report";
/* Who is close to today's relay cap (v484, H: "Notify me when a user is about to hit his limit."). The caps live in
   supabase/functions/ai-relay/index.ts and this is a SECOND COPY of them: the report reads a table, not the function's
   constants, so the two must be changed together. The copy is named rather than hidden because the cost of drift is a
   warning at the wrong number in a report only H reads — it cannot refuse a call or change what a phone may do.
   The owner's own phone is skipped wherever this is used: it is exempt from the per-provider caps. Owner's, English. */
const RELAY_CAPS={qwen:80,deepseek:400}, RELAY_WARN=0.8;
function relayNear(r){ const out=[]; for(const [pv,cap] of Object.entries(RELAY_CAPS)){ const c=+(r&&r["relay_"+pv])||0; if(c>=Math.ceil(cap*RELAY_WARN)) out.push({pv,c,cap}); } return out; }
const relayInstall=r=>((r&&r.data||{}).install)||(r&&r.install)||"";
function relayNearRows(rows){ const me=installId(); return (rows||[]).filter(r=>relayInstall(r)!==me).map(r=>({r,near:relayNear(r)})).filter(x=>x.near.length); }
const relayNearText=near=>near.map(x=>`${x.pv} ${x.c} of ${x.cap}`).join(", ");
let USERS=null, FEEDBACK=null; /* the last answers: {at, rows} */
async function fetchAllUsers(){ return USERS=await fetchReport("users"); }
/* On unlock, fetch the report once and put a line above the tab bar when a phone is close to its relay cap (v484).
   There is no push channel to build on — the app has no service-worker push handler and FCM is blocked in China, so
   the unlock is the moment H is actually looking at the owner's rows. The answer is cached in USERS, so All users
   costs no second call. A failure is silent on purpose: the row's own Show is where an error belongs (v198). */
async function relayWatch(){
  try{ const u=await fetchAllUsers(), near=relayNearRows(u.rows);
    if(!near.length) return;
    noteBar(near.length===1?`One phone is near today's relay cap: ${relayNearText(near[0].near)}.`:`${near.length} phones are near today's relay cap — see All users.`);
  }catch(e){}
}
async function fetchFeedback(){ return FEEDBACK=await fetchReport("feedback"); }
async function fetchReport(what){
  const r=await fetch(reportUrl(),{method:"POST",headers:{"content-type":"application/json","apikey":SHARE_KEY,"authorization":"Bearer "+SHARE_KEY},body:JSON.stringify({password:S.adminPw||"",what})});
  if(!r.ok){ /* v198 — the phone showed a 401 that the function's own "wrong password" could not be told from Supabase's JWT gate: name the sender */
    const body=await r.text().catch(()=>""); logErr("report",r.status+": "+body.slice(0,300));
    if(r.status===401){ if(/jwt/i.test(body)) throw new Error("the report function still checks the JWT — switch off \"Verify JWT\" under its Settings in the dashboard");
      if(/wrong password/i.test(body)) throw new Error("the report function does not accept the app password — deploy the current usage-report code from the repo, it carries the password's hash");
      throw new Error("the report function refused the call (401): "+(body.slice(0,120)||"no details")); }
    if(r.status===404||r.status===503) throw new Error("the report function is not set up");
    throw new Error("report error "+r.status+": "+(body.slice(0,120)||"no details")); }
  const rows=await r.json(); if(!Array.isArray(rows)) throw new Error("unexpected answer");
  return {at:Date.now(),rows};
}
/* Feedback (v212, H: "add a provide feedback function — of course I must receive this feedback", described first and built on
   "Go"): a user's message goes as one row into the table `feedback` of H's project (insert only for the publishable key,
   with the installation id and the app version — no name, no cards, no photos); H reads them through the report function
   with what:"feedback" (supabase/feedback.sql, the function's second branch). */
/* A screenshot with the message (v511, H: "Unter Feedback bitte folgendes ermöglichen: Screenshot anhängen"): a picture says in one
   look what a sentence takes a paragraph to describe, and H's own reports to me are screenshots. The picture is downscaled here and
   travels as base64 in the row's own `shot` column, so nothing new is set up on the phone — the one thing the OWNER has to do once is
   `supabase/feedback-shot.sql`, which adds that column, widens the insert policy and lets feedback_list hand it back. Until he has,
   PostgREST answers 400 PGRST204 ("column shot ... does not exist"), and the message is then sent WITHOUT the picture rather than
   lost: sendFeedback returns "noshot" and the row says so. FB_SHOT_MAX 1400 px and the quality ladder keep the base64 under
   FB_SHOT_B64, which is what the policy allows — a phone screenshot at 1400 px is 150–400 KB of JPEG, so the ladder rarely steps. */
const FB_SHOT_MAX=1400, FB_SHOT_B64=900000;
let FB_SHOT=null; /* {b64,size,url}: the picture staged under the Feedback box, memory only — a message that is never sent leaves nothing behind */
async function shrinkShot(file){
  const bmp=await createImageBitmap(file);
  const sc=Math.min(1,FB_SHOT_MAX/Math.max(bmp.width,bmp.height));
  const cv=document.createElement("canvas"); cv.width=Math.max(1,Math.round(bmp.width*sc)); cv.height=Math.max(1,Math.round(bmp.height*sc));
  cv.getContext("2d").drawImage(bmp,0,0,cv.width,cv.height); bmp.close();
  for(const q of [0.75,0.6,0.45,0.3]){ /* the ladder: a busy screenshot at 1400 px can pass the policy's ceiling, and a smaller picture is better than no picture */
    const blob=await new Promise(res=>cv.toBlob(res,"image/jpeg",q)); if(!blob) break;
    const b64=await blobToB64(blob);
    if(b64.d.length<=FB_SHOT_B64) return {b64:b64.d,size:blob.size,url:URL.createObjectURL(blob)};
  }
  throw new Error("the picture is too large");
}
const fbShotHTML=()=>FB_SHOT?`<div class="fbthumb"><img src="${FB_SHOT.url}" alt="${esc(t("Add screenshot"))}"><button class="x" id="fb-shot-x" aria-label="${esc(t("Remove image"))}">×</button><span class="sz">${Math.round(FB_SHOT.size/1024)} KB</span></div>`:"";
function fbShotDrop(){ if(FB_SHOT&&FB_SHOT.url) URL.revokeObjectURL(FB_SHOT.url); FB_SHOT=null; }
function fbShotDraw(){ const box=$("#fb-shot"); if(!box) return; box.innerHTML=fbShotHTML(); const x=$("#fb-shot-x"); if(x) x.onclick=()=>{ fbShotDrop(); fbShotDraw(); }; }
async function sendFeedback(text,shot){
  const post=body=>fetch(SHARE_URL+"/rest/v1/feedback",{method:"POST",headers:{"apikey":SHARE_KEY,"Authorization":"Bearer "+SHARE_KEY,"Content-Type":"application/json","Prefer":"return=minimal"},body:JSON.stringify(body)});
  const row={install:installId(),version:APP_V,text};
  let r=await post(shot?{...row,shot}:row);
  if(!r.ok&&shot){ const body=await r.text().catch(()=>""); if(r.status===400&&/shot/.test(body)){ logErr("feedback","the feedback table has no shot column yet: "+body.slice(0,160)); r=await post(row); if(r.ok) return "noshot"; } /* the owner has not run feedback-shot.sql: the message goes without the picture rather than not at all */
    else { logErr("feedback",r.status+": "+body.slice(0,300)); throw new Error(r.status===404?"the feedback table is not set up":"error "+r.status); } }
  if(!r.ok){ const body=await r.text().catch(()=>""); logErr("feedback",r.status+": "+body.slice(0,300)); throw new Error(r.status===404?"the feedback table is not set up":"error "+r.status); }
  return "";
}
