  for(let i=n-1;i>=0;i--){ const x=new Date(); x.setDate(now.getDate()-i); const k=dayKey(x);
    out.push({w:dayOf(daily[k]).w||0,lbl:x.toLocaleDateString(LANG_LOCALE[LANG]||LANG,{weekday:"short"})}); }
