  return `<div class="recap one py" aria-live="polite"><div class="rp" style="font-size:min(${RECAP_PY}px,84cqw,${(143/n).toFixed(2)}cqw)">${esc(py)}</div>${mn?`<div class="rm" style="font-size:min(20px,8.2cqw)">${esc(mn)}</div>`:""}</div>`;
