/* the note waits until it is tapped away (v416, H: "Was mich uebrigens an dem Update Pop-up gestoert hat, ist, dass es ziemlich
   schnell wieder weggeht. Koennen wir das nicht so machen, dass man das aktiv irgendwie wegklicken muss? Und damit es nicht nervt
   koennen wir im menu ja ein haekchen fuer update notifications on/off setzen. Default on."): the timer of v408–v415 is gone, since
   a line nobody finished reading is the fault v413 spent a version on. Setting "updateNote", absent = on. */
const updateNoteOn=()=>S.settings.updateNote!==false;
const newsList=()=>Object.keys(WHATS_NEW).map(Number).sort((a,b)=>b-a);
const newsSince=v=>newsList().filter(n=>n>v&&n<=APP_V).map(n=>({v:n,s:WHATS_NEW[n]})); /* what this phone has not been shown yet, newest first */
/* v551: the notes no longer carry their build number. v225 took the version label off the header as "a developer's line,
   not a user's" and About then printed five of them under it — "v550 — ...", "v549 — ...": five numbers a learner cannot
   act on, above a sentence they can. The build is still named once, at the head of this same row (aboutText's "PWA vN."). */
function whatsNewHTML(){ const ns=newsList().slice(0,5); if(!ns.length) return "";
  return `<div class="s" style="margin-top:8px">${esc(t("What is new"))}</div>`+ns.map(n=>`<div class="s">${esc(t(WHATS_NEW[n]))}</div>`).join(""); }
function hideUpdated(){ const e=$("#updated"); if(e) e.remove(); }
/* the line above the tab bar: the update note's own element and place (v413/v416), shared with the owner's
   near-cap warning (v484) so the two cannot stack or drift apart in look */
function noteBar(text){
  hideUpdated();
  const el=document.createElement("div"); el.className="undo"; el.id="updated"; el.setAttribute("role","status");
  el.innerHTML=`<span class="t">${esc(text)}</span><button class="x" type="button" aria-label="${esc(t("Close"))}">✕</button>`;
  el.onclick=hideUpdated; /* the whole line takes the tap, not only the × */
  document.body.appendChild(el);
}
function showUpdated(notes){
  const more=notes.length>1?" "+t("More under About."):"";
  noteBar((notes.length?t("Updated — {0}",t(notes[0].s)):t("Updated."))+more);
}
/* at boot, once: a phone that has seen a version before and now runs a newer one gets the line. A fresh install writes
   the version down and says nothing — there is nothing it was updated from. */
function updateNote(){
  const seen=+S.settings.seenVer||0;
  setSetting("seenVer",APP_V).catch(()=>{});
  if(!seen||seen>=APP_V||!updateNoteOn()) return; /* the version is written down either way, so switching the note on later does not flood */
  showUpdated(newsSince(seen));
}
const UNDO_MS=5000; let UNDO=null;
/* the Undo line and the update note share the one place above the tab bar (v416): the user's own action wins */
function undoText(){
  const cards=UNDO.items.filter(i=>i.kind==="card"), photos=UNDO.items.filter(i=>i.kind==="photo");
  if(cards.length&&photos.length) return t("Deleted {0} and {1}",nOf(cards.length,"card"),nOf(photos.length,"photo"));
  if(cards.length===1) return cards[0].d.c?t("Deleted “{0}”",cards[0].d.c.replace(/\n/g," / ")):t("Card deleted");
  if(cards.length) return t("Deleted {0}",nOf(cards.length,"card"));
  if(photos.length===1) return t("Photo deleted");
  return t("Deleted {0}",nOf(photos.length,"photo"));
}
function showUndo(item){
  hideUpdated(); /* the two share the one place above the tab bar (v416) */
  if(!UNDO) UNDO={items:[],timer:null};
  UNDO.items.push(item); clearTimeout(UNDO.timer); UNDO.timer=setTimeout(hideUndo,UNDO_MS);
  let el=$("#undo");
  if(!el){ el=document.createElement("div"); el.className="undo"; el.id="undo"; el.setAttribute("role","status"); el.innerHTML=`<span class="t"></span><button id="undo-btn">${t("Undo")}</button>`; el.querySelector("#undo-btn").onclick=undoDelete; document.body.appendChild(el); }
  el.querySelector(".t").textContent=undoText();
}
function hideUndo(){ if(UNDO) clearTimeout(UNDO.timer); UNDO=null; const el=$("#undo"); if(el) el.remove(); }
/* Marking many cards or photos and deleting them together (v351, H: "implement a function to batch mark and delete cards
   and photos" — described first, "Go"): Select on the Cards list and in the inbox head puts the screen into marking, a tap
   on a row marks it instead of opening it, All marks everything the list shows (the filter and the search decide what that
   is), and a bar above the tab bar carries "Delete N" and Done. The deletion runs through the same delCustom / delShot as a
   single one, so the Undo line of v268 says "Deleted 12 cards" and five seconds put everything back. */
let PICK=null; /* {kind:"cards"|"shots", set:Set of ids} while marking */
const marking=k=>!!(PICK&&PICK.kind===k);
function endPick(){ PICK=null; const el=$("#pickbar"); if(el) el.remove(); }
function pickToggle(id){ if(PICK) PICK.set.has(id)?PICK.set.delete(id):PICK.set.add(id); }
/* A long press starts the marking (v354, H's screenshot of the cramped chip row: "Der card selection mode sieht kaese aus.
   Ist zu eng. Wie waer's mit longpress auf karte enters selection mode?"): the Select button is gone from the Cards chip row
   and from the inbox head — press and hold a card or a photo for half a second instead, and it is marked. A press that
   turns into a scroll or a drag cancels; the click that follows the press is not a tap (LP_EAT), so the row does not toggle
   itself off again. */
const LP_MS=500, LP_MOVE=10, LP_EAT=250, LP_MAX=5000;
